INSERT INTO `mod_archaeology_project` (`id`, `race`, `name`, `description`, `rare`, `item`, `cost`, `sockets`, `min_skill`, `chance`, `cata_class`, `cata_subclass`) VALUES
(9, 1, 'Pewter Drinking Cup', 'The dwarves of Ironforge were originally composed of three clans: the Bronzebeards, the Wildhammers and the Dark Irons. As the result of a civil war, the Bronzebeards were left in control of the city of Ironforge while the Wildhammers eventually retreated to the Hinterlands and Twilight Highlands. The Dark Iron dwarves came to dwell in between the Redridge Mountains and the Burning Steppes, in the shadow of Blackrock Mountain.', 0, 9504020, 35, 1, 0, 100.0, 15, 4),
(40, 1, 'Ceramic Funeral Urn', 'The dwarves of Ironforge were originally composed of three clans: the Bronzebeards, the Wildhammers and the Dark Irons. As the result of a civil war, the Bronzebeards were left in control of the city of Ironforge while the Wildhammers eventually retreated to the Hinterlands and Twilight Highlands. The Dark Iron dwarves came to dwell in between the Redridge Mountains and the Burning Steppes, in the shadow of Blackrock Mountain.', 0, 9504021, 35, 1, 0, 100.0, 15, 4),
(42, 1, 'Worn Hunting Knife', 'The dwarves of Ironforge were originally composed of three clans: the Bronzebeards, the Wildhammers and the Dark Irons. As the result of a civil war, the Bronzebeards were left in control of the city of Ironforge while the Wildhammers eventually retreated to the Hinterlands and Twilight Highlands. The Dark Iron dwarves came to dwell in between the Redridge Mountains and the Burning Steppes, in the shadow of Blackrock Mountain.', 0, 9504022, 30, 0, 0, 100.0, 15, 4),
(44, 1, 'Bone Gaming Dice', 'The dwarves of Ironforge were originally composed of three clans: the Bronzebeards, the Wildhammers and the Dark Irons. As the result of a civil war, the Bronzebeards were left in control of the city of Ironforge while the Wildhammers eventually retreated to the Hinterlands and Twilight Highlands. The Dark Iron dwarves came to dwell in between the Redridge Mountains and the Burning Steppes, in the shadow of Blackrock Mountain.', 0, 9504023, 32, 0, 0, 100.0, 15, 4),
(70, 1, 'Stone Gryphon', 'The dwarves of Ironforge were originally composed of three clans: the Bronzebeards, the Wildhammers and the Dark Irons. As the result of a civil war, the Bronzebeards were left in control of the city of Ironforge while the Wildhammers eventually retreated to the Hinterlands and Twilight Highlands. The Dark Iron dwarves came to dwell in between the Redridge Mountains and the Burning Steppes, in the shadow of Blackrock Mountain.', 0, 9504024, 35, 1, 0, 100.0, 15, 4),
(72, 1, 'Silver Neck Torc', 'The dwarves of Ironforge were originally composed of three clans: the Bronzebeards, the Wildhammers and the Dark Irons. As the result of a civil war, the Bronzebeards were left in control of the city of Ironforge while the Wildhammers eventually retreated to the Hinterlands and Twilight Highlands. The Dark Iron dwarves came to dwell in between the Redridge Mountains and the Burning Steppes, in the shadow of Blackrock Mountain.', 0, 9504025, 34, 1, 0, 100.0, 15, 4),
(77, 8, 'Zandalari Voodoo Doll', 'The earliest known trolls belonged to the Zandalar tribe, from which all other trolls are descended. The Zandalari were regarded as an overarching priest caste for all trolls and worked tirelessly to record and preserve troll society and traditions. Of the many tribes that split off from the Zandalari, the two most dominant were the Gurubashi and Amani.', 0, 9504026, 27, 0, 0, 100.0, 15, 4),
(87, 8, 'Fetish of Hir''eek', 'The earliest known trolls belonged to the Zandalar tribe, from which all other trolls are descended. The Zandalari were regarded as an overarching priest caste for all trolls and worked tirelessly to record and preserve troll society and traditions. Of the many tribes that split off from the Zandalari, the two most dominant were the Gurubashi and Amani.', 0, 9504027, 30, 0, 0, 100.0, 15, 4),
(89, 8, 'Lizard Foot Charm', 'The earliest known trolls belonged to the Zandalar tribe, from which all other trolls are descended. The Zandalari were regarded as an overarching priest caste for all trolls and worked tirelessly to record and preserve troll society and traditions. Of the many tribes that split off from the Zandalari, the two most dominant were the Gurubashi and Amani.', 0, 9504028, 32, 0, 0, 100.0, 15, 4),
(91, 1, 'Wooden Whistle', 'The dwarves of Ironforge were originally composed of three clans: the Bronzebeards, the Wildhammers and the Dark Irons. As the result of a civil war, the Bronzebeards were left in control of the city of Ironforge while the Wildhammers eventually retreated to the Hinterlands and Twilight Highlands. The Dark Iron dwarves came to dwell in between the Redridge Mountains and the Burning Steppes, in the shadow of Blackrock Mountain.', 0, 9504029, 28, 0, 0, 100.0, 15, 4),
(93, 1, 'Belt Buckle with Anvilmar Crest', 'The dwarves of Ironforge were originally composed of three clans: the Bronzebeards, the Wildhammers and the Dark Irons. As the result of a civil war, the Bronzebeards were left in control of the city of Ironforge while the Wildhammers eventually retreated to the Hinterlands and Twilight Highlands. The Dark Iron dwarves came to dwell in between the Redridge Mountains and the Burning Steppes, in the shadow of Blackrock Mountain.', 0, 9504030, 34, 0, 0, 100.0, 15, 4),
(95, 3, 'Black Trilobite', 'Fossils are the preserved remains of animals or plants from the ancient past. Typically the living tissues are replaced with minerals that preserve the form of the original organism.', 0, 9504031, 31, 0, 0, 100.0, 15, 4),
(97, 3, 'Beautiful Preserved Fern', 'Fossils are the preserved remains of animals or plants from the ancient past. Typically the living tissues are replaced with minerals that preserve the form of the original organism.', 0, 9504032, 25, 0, 0, 100.0, 15, 4),
(99, 4, 'Highborne Pyxis', 'The kaldorei are one of the most ancient races of Azeroth. One of the darkest moments in their history occurred when the quel''dorei, or Highborne - the highest caste of elven nobility - unleashed dangerous magic that brought the Burning Legion into the world and resulted in countless deaths.', 0, 9504033, 30, 0, 0, 100.0, 15, 4),
(101, 4, 'Inlaid Ivory Comb', 'The kaldorei are one of the most ancient races of Azeroth. One of the darkest moments in their history occurred when the quel''dorei, or Highborne - the highest caste of elven nobility - unleashed dangerous magic that brought the Burning Legion into the world and resulted in countless deaths.', 0, 9504034, 30, 0, 0, 100.0, 15, 4),
(103, 4, 'Scandalous Silk Nightgown', 'The kaldorei are one of the most ancient races of Azeroth. One of the darkest moments in their history occurred when the quel''dorei, or Highborne - the highest caste of elven nobility - unleashed dangerous magic that brought the Burning Legion into the world and resulted in countless deaths.', 0, 9504035, 30, 0, 0, 100.0, 15, 4),
