(9504063, 15, 4, 'Highborne Soul Mirror', 950463, 3, 8000, 2000, 0, -1, -1, 1, 1, 1, 'While the glass has been shattered into a thousand fragments, the detailed work of the mirror''s frame itself convinces you that this artifact was once highly magical, and might still be if every piece could be recovered.'),
(9504064, 15, 4, 'Druid and Priest Statue Set', 950464, 3, 433160, 108290, 0, -1, -1, 1, 1, 1, 'These are the remains of a pair of statues of precious metal. They do not seem carved or molded so much as grown, as if free from an artisan''s touch. Both figures are night elves.'),
(9504065, 15, 4, 'Dented Shield of Horuz Killcrow', 950465, 0, 400000, 100000, 0, -1, -1, 0, 1, 1, ''),
(9504066, 15, 4, 'Scorched Staff of Shadow Priest Anund', 950466, 0, 400000, 100000, 0, -1, -1, 0, 1, 1, ''),
(9504067, 15, 4, 'Scepter of Charlga Razorflank', 950467, 0, 400000, 100000, 0, -1, -1, 0, 1, 1, ''),
