(9504069, 15, 4, 'Skull Staff of Shadowforge', 950469, 0, 400000, 100000, 0, -1, -1, 0, 1, 1, ''),
(9504070, 15, 4, 'Clockwork Gnome', 950470, 3, 0, 0, 0, -1, -1, 1, 1, 1, 'You have found a few pieces of a mechanical construct of apparently high technology. It''s possible these parts come from one of the mechanognomes of Northrend. Why dwarves would have relocated the parts here is a mystery.'),
(9504071, 15, 4, 'Chalice of the Mountain Kings', 950471, 3, 16000, 4000, 0, -1, -1, 1, 1, 1, 'You can tell right away that this drinking cup holds far more significance than mere drinking (not that dwarves have any problem with mere drinking). The bit of runes you can make out suggest a ceremonial purpose.'),
(9504072, 15, 4, 'Tooth with Gold Filling', 950472, 0, 2000000, 500000, 0, -1, -1, 0, 1, 1, ''),
(9504073, 15, 4, 'Drakkari Sacrificial Knife', 950473, 0, 400000, 100000, 0, -1, -1, 0, 1, 1, ''),
(9504074, 15, 4, 'Zin''rokh, Destroyer of Worlds', 950474, 4, 0, 0, 0, -1, -1, 1, 1, 1, 'It is clear that you have recovered a piece of a very powerful troll weapon. Can it be reforged?'),
(9504075, 15, 4, 'String of Small Pink Pearls', 950475, 0, 400000, 100000, 0, -1, -1, 0, 1, 1, ''),
(9504076, 15, 4, 'Chest of Tiny Glass Animals', 950476, 0, 4000000, 1000000, 0, -1, -1, 0, 1, 1, ''),
