(9504078, 15, 4, 'Scepter of Xavius', 950478, 0, 400000, 100000, 0, -1, -1, 0, 1, 1, ''),
(9504079, 15, 4, 'Kaldorei Wind Chimes', 950479, 3, 32000, 8000, 0, -1, -1, 1, 1, 1, 'There is something unusual about these bronze tubes. You detect a hint of magic that still resides within. When placed near each other or even within your pack, the fragments of the tubes seem to move closer to each other.'),
(9504080, 15, 4, 'Queen Azshara''s Dressing Gown', 950480, 4, 136660, 34165, 0, -1, -1, 1, 1, 1, 'The rumors of the Highborne''s poor fashion sense seem to be true.'),
(9504081, 15, 4, 'Feathered Raptor Arm', 950481, 0, 400000, 100000, 0, -1, -1, 0, 1, 1, ''),
