(9504100, 15, 4, 'Dignified Portrait', 950500, 0, 400000, 100000, 0, -1, -1, 0, 1, 1, ''),
(9504101, 15, 4, 'Arrival of the Naaru', 950501, 3, 40000, 10000, 0, -1, -1, 1, 1, 1, 'The naaru are a near god-like race of energy beings who are strongly aligned with the Light. The naaru first came into contact with the draenei when Prophet Velen prayed for help to escape the corruption of the Burning Legion.'),
(9504102, 15, 4, 'The Last Relic of Argus', 950502, 3, 40000, 10000, 0, -1, -1, 1, 1, 1, 'This is a simple draenei crystal that appears to be thousands of years old. You are fairly certain that it is not of this world.'),
