(9504124, 15, 4, 'Word of Empress Zoe', 950524, 0, 15000000, 3750000, 0, -1, -1, 0, 1, 1, ''),
(9504125, 15, 4, 'Scepter of Bronzebeard', 950525, 0, 800000, 200000, 0, -1, -1, 0, 1, 1, ''),
(9504126, 15, 4, 'The Innkeeper''s Daughter', 950526, 3, 652632, 163158, 0, -1, -1, 1, 1, 1, 'This small stone resembles a Hearthstone. It is warm to the touch and makes very faint giggling noises at inopportune moments.'),
(9504127, 15, 4, 'Staff of Sorcerer-Thane Thaurissan', 950527, 4, 0, 0, 0, -1, -1, 1, 1, 1, 'The pieces of this staff still crackle with energy. Yet it also appears to have suffered extensive fire damage.'),
(9504128, 15, 4, 'Tyrande''s Favorite Doll', 950528, 4, 0, 0, 0, -1, -1, 1, 1, 1, 'This is a simple night elven doll. The hands and feet are of porcelain, painted with flaking purple. The garments are fine but fraying. The doll''s long tresses are the most remarkable and could possibly be real night elf hair.'),
(9504129, 15, 4, 'Bones of Transformation', 950529, 4, 200000, 50000, 0, -1, -1, 1, 1, 1, 'These bones show a curious mixture of humanoid arms and serpentine tail, convincing you that they are probably from a naga. What is more interesting is that the skeleton has been articulated and posed as if it was once displayed in a museum.'),
(9504130, 15, 4, 'Carcanet of the Hundred Magi', 950530, 0, 800000, 200000, 0, -1, -1, 0, 1, 1, ''),
