(9504137, 15, 4, 'Shard of Petrified Wood', 950537, 0, 40000, 10000, 0, -1, -1, 0, 1, 1, ''),
(9504138, 15, 4, 'Strange Velvet Worm', 950538, 0, 40000, 10000, 0, -1, -1, 0, 1, 1, ''),
(9504139, 15, 4, 'Fine Bloodscalp Dinnerware', 950539, 0, 40000, 10000, 0, -1, -1, 0, 1, 1, ''),
(9504140, 15, 4, 'Extinct Turtle Shell', 950540, 4, 0, 0, 0, -1, -1, 1, 1, 1, 'This turtle shell is supernaturally resilient. Perhaps if you collected all the fragments, you could assemble a powerful protective device.'),
(9504141, 15, 4, 'Haunted War Drum', 950541, 3, 0, 0, 0, -1, -1, 1, 1, 1, 'What appears to be an ancient, elaborate troll war drum. The hide is of an unusual color and appears to have been tattooed rather than simply painted or dyed.'),
(9504142, 15, 4, 'Ancient Amber', 950542, 3, 0, 0, 0, -1, -1, 1, 1, 1, 'A particularly large hunk of petrified tree resin containing what appears to be a small humanoid figure.'),
(9504143, 15, 4, 'Vrykul Drinking Horn', 950543, 3, 0, 0, 0, -1, -1, 1, 1, 1, 'A large, sturdy, silver-chased and rune-carved horn.'),
(9504144, 15, 4, 'Pterrordax Hatchling', 950544, 3, 0, 0, 0, -1, -1, 1, 1, 1, 'Could this fossilized egg still be... alive?!'),
(9504145, 15, 4, 'Voodoo Figurine', 950545, 3, 0, 0, 0, -1, -1, 1, 1, 1, 'A medium-sized figurine of unusual complexity and troll manufacture.');
